var SEO_TAB="overview";
/* The SEO agent (cron step agent, 09:00 plan, 13:00 work, 19:00 report IST): its plan, timeline, tasks and reports. Reports are Markdown (also on GitHub); mdHtml renders the few forms the agent writes, escaped first. */
var OWNER_TAG={auto:'<span class="tag tag-blue">Agent</span>',wait:'<span class="tag">Waiting</span>',code:'<span class="tag tag-warn">Code fix</span>',person:'<span class="tag tag-saffron">Person</span>'};
function mdHtml(md){var out=[],inl=function(t){return esc(t).replace(/\*\*([^*]+)\*\*/g,"<b>$1</b>").replace(/\[([^\]]+)\]\((https:\/\/[^)\s]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>')},list=null;
  String(md||"").split("\n").forEach(function(l){var m;
    if((m=/^(#{1,3}) (.*)/.exec(l))){if(list){out.push("</"+list+">");list=null}out.push(m[1].length===1?'<h4 class="mdh">'+inl(m[2])+'</h4>':'<h5 class="mdh">'+inl(m[2])+'</h5>');return}
    if((m=/^(- |\d+\. )(.*)/.exec(l))){var t=m[1]==="- "?"ul":"ol";if(list!==t){if(list)out.push("</"+list+">");out.push("<"+t+' class="mdl">');list=t}out.push("<li>"+inl(m[2])+"</li>");return}
    if((m=/^  (.+)/.exec(l))&&list){out[out.length-1]=out[out.length-1].replace(/<\/li>$/,'<br><span class="small muted">'+inl(m[1])+"</span></li>");return}
    if(list){out.push("</"+list+">");list=null}if(l.trim())out.push("<p>"+inl(l)+"</p>")});
  if(list)out.push("</"+list+">");return out.join("")}
