  var day=(a.log||[])[0]?a.log[0].day:null,today=(a.log||[]).filter(function(l){return l.day===day}).slice().reverse();
  var h='<div class="seogrid"><section class="tcard" id="agentStatus"><h4>'+ic("check")+'The agent\'s day</h4><p class="note">It reads every nightly audit result, keeps the task list below, fixes what it can on its own (re-runs failed steps, re-audits pages to confirm fixes, pings IndexNow and resubmits the sitemap for pages search engines do not know, and writes the content gaps through the topic pipeline), and lists what needs code or a person. Plan at '+esc(sch.plan||"09:00")+', work at '+esc(sch.work||"13:00")+', report at '+esc(sch.report||"19:00")+' IST.</p>'+
    '<p><b>Last run:</b> '+(a.last_run?esc(fmtT(a.last_run)):'not yet')+' · <a href="'+esc(a.repo||"#")+'" target="_blank" rel="noopener">Every report on GitHub</a></p>'+
    '<div class="jcounts">'+[[by.auto,"Agent handles"],[by.wait,"Waiting on Google or Bing"],[by.code,"Need a code change"],[by.person,"Need a person"],[(a.fixed||[]).length,"Fixed this week"]].map(function(x){return '<div class="jcount"><b>'+x[0]+'</b><span>'+x[1]+'</span></div>'}).join("")+'</div></section>';
  h+='<section class="tcard" id="agentToday"><h4>'+ic("track")+'Today\'s timeline'+(day?' ('+esc(fmtDate(day))+')':'')+'</h4>'+(today.length?'<ul class="rows seolog">'+today.map(function(l){return '<li class="row"><div>'+(l.ok===false?ic("alert"):ic(l.kind==="action"?"fix":l.kind==="plan"?"news":l.kind==="report"?"news":"check"))+'</div><div><b>'+esc(l.text)+'</b><div class="meta">'+esc(fmtT(l.at))+' · '+esc(l.phase||"")+'</div></div></li>'}).join("")+'</ul>':'<div class="empty">Nothing logged yet today.</div>')+'</section></div>';
  h+='<section class="tcard" id="agentWeek"><h4>'+ic("news")+'This week\'s plan</h4>'+(weekly?'<div class="mdbody">'+mdHtml(weekly.markdown)+'</div>':'<div class="empty">The first weekly plan is written at the next 09:00 IST run.</div>')+'</section>';
  h+='<section class="tcard"><h4>'+ic("fix")+'Open tasks ('+open.length+')</h4>'+(open.length?'<table class="tbl seotbl" id="agentTasks"><thead><tr><th scope="col">Task</th><th scope="col">Who acts</th><th scope="col">Since</th><th scope="col">What happens</th></tr></thead><tbody>'+open.map(function(t){return '<tr><td class="n"><b>'+esc(t.title)+'</b>'+(t.detail?'<div class="meta">'+esc(t.detail)+'</div>':'')+'</td><td data-l="Who acts">'+(OWNER_TAG[t.owner]||esc(t.owner))+' <span class="tag'+(t.severity==="high"?' tag-danger':'')+'">'+esc(t.severity)+'</span></td><td data-l="Since">'+esc(fmtDate(t.first_seen))+'</td><td data-l="What happens" class="small">'+esc(t.action||"")+(t.last_result?'<div class="meta">Last: '+esc(t.last_result)+' ('+esc(fmtT(t.last_action_at))+')</div>':'')+'</td></tr>'}).join("")+'</tbody></table>':'<div class="empty">No open tasks.</div>')+
    ((a.fixed||[]).length?'<h5 class="mdh">Fixed in the last 7 days</h5><ul class="mdl">'+a.fixed.map(function(t){return '<li>'+esc(t.title)+' <span class="small muted">'+esc(fmtT(t.resolved_at))+'</span></li>'}).join("")+'</ul>':'')+'</section>';
