  var cd=e.target.closest("[data-seo-cdraft]");if(cd&&SEOD){var cid=cd.getAttribute("data-seo-cdraft"),cc=catById(cid);if(!cc)return;$("contentTab").click();$("postNew").click();$("pKind").value="story";$("pTitle").value=cc.label+" in Gurugram: what residents are reporting and who fixes it";$("pTags").value=cid;$("pSummary").value="";$("pTitle").focus();return}
